const COMMANDS: &[&str] = &["current"];

fn main() {
    // Writes the per-command permissions under permissions/autogenerated and,
    // when building for Android, copies the Tauri native API next to the
    // plugin and registers the Gradle module. There is no iOS package: iOS has
    // no fold API, so the command answers null from Rust alone.
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .build();
}
